import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const defaultRoot = process.cwd();
const appPath = "app.js";
const outputPath = path.join("data", "timeline-bundle.js");

function readText(root, relativePath) {
  return fs.readFileSync(path.join(root, relativePath), "utf8");
}

function readJson(root, relativePath) {
  return JSON.parse(readText(root, relativePath));
}

function normalizeDataFile(file) {
  return file.replace(/^\.\//, "");
}

function extractStringArray(source, name) {
  const pattern = new RegExp(`const\\s+${name}\\s*=\\s*(?:new\\s+Set\\()?\\[([\\s\\S]*?)\\]\\)?;`);
  const match = source.match(pattern);
  if (!match) {
    throw new Error(`Could not find ${name} in ${appPath}`);
  }
  return [...match[1].matchAll(/["']([^"']+)["']/g)].map((entry) => entry[1]);
}

function extractDataVersion(source) {
  const match = source.match(/const\s+dataVersion\s*=\s*['"]([^'"]+)['"]/);
  if (!match) {
    throw new Error(`Could not find dataVersion in ${appPath}`);
  }
  return match[1];
}

export function buildTimelineBundle(root = defaultRoot) {
  const appSource = readText(root, appPath);
  const dataVersion = extractDataVersion(appSource);
  const dataFiles = extractStringArray(appSource, "dataFiles").map(normalizeDataFile);
  const supplementalDataFiles = extractStringArray(appSource, "supplementalDataFiles").map(normalizeDataFile);
  const events = dataFiles.flatMap((file) => readJson(root, file).map((event) => ({ ...event, dataFile: file })));
  const log = readJson(root, "data/ingestion-log.json");
  const bundle = {
    dataVersion,
    generatedAt: new Date().toISOString(),
    dataFiles,
    supplementalDataFiles,
    eventCount: events.length,
    logCount: log.length,
    events,
    log,
  };
  const absoluteOutputPath = path.join(root, outputPath);
  fs.mkdirSync(path.dirname(absoluteOutputPath), { recursive: true });
  fs.writeFileSync(
    absoluteOutputPath,
    `/* generated by tools/build-timeline-bundle.mjs */\nwindow.LEEAO_TIMELINE_BUNDLE=${JSON.stringify(bundle)};\n`,
    "utf8",
  );
  return {
    outputPath,
    dataVersion,
    dataFileCount: dataFiles.length,
    eventCount: events.length,
    logCount: log.length,
  };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  console.log(JSON.stringify(buildTimelineBundle(defaultRoot), null, 2));
}
